/*
 * A069764  Frobenius number of the numerical semigroup generated by
 *          consecutive octahedral numbers.
 * https://oeis.org/A069764
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = ((1/3)*n*(2*n^2+1)-1) * ((1/3)*(n+1)*(2*(n+1)^2+1)-1) - 1
 *            (defined for n ≥ 2, offset 2)
 * Range:     u8 n <= 2, u16 n <= 6, u32 n <= 45, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n < 2) return 0;               /* offset not defined; safe fallback */
    seq_t sn   = (seq_t)n;
    seq_t sn1  = sn + 1;

    /* Compute (1/3)*n*(2*n^2+1) - 1 */
    seq_t term1 = sn * ((seq_t)2 * sn * sn + 1);
    term1 /= 3;
    term1 -= 1;

    /* Compute (1/3)*(n+1)*(2*(n+1)^2+1) - 1 */
    seq_t term2 = sn1 * ((seq_t)2 * sn1 * sn1 + 1);
    term2 /= 3;
    term2 -= 1;

    /* Final product minus 1 */
    return term1 * term2 - 1;
}
